INSERT INTO "SELECT
      c.name_bg                                  AS asbis_root,
      COUNT(ch.id)                               AS children_count,
      STRING_AGG(ch.name_bg, ' | ' ORDER BY ch.name_bg) AS children
  FROM categories c
  LEFT JOIN categories ch ON ch.parent_id = c.id
  WHERE c.platform = 'ASBIS'
    AND c.parent_id IS NULL
  GROUP BY c.id, c.name_bg
  ORDER BY children_count DESC, c.name_bg" (asbis_root,children_count,children) VALUES
